import sys

def transform(A, columns):
    for col in columns:
        A.sort(key=lambda row: row[col - 1])
    return A

def can_transform(A, B, n, m):
    if A == B:
        return [0]

    for i in range(1, m + 1):
        sorted_A = transform([row[:] for row in A], [i])
        if sorted_A == B:
            return [1, i]

        for j in range(i + 1, m + 1):
            doubly_sorted_A = transform([row[:] for row in sorted_A], [j])
            if doubly_sorted_A == B:
                return [2, i, j]

    return [-1]

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    index = 0
    n = int(data[index])
    index += 1
    m = int(data[index])
    index += 1

    A = []
    for _ in range(n):
        row = list(map(int, data[index:index + m]))
        A.append(row)
        index += m

    B = []
    for _ in range(n):
        row = list(map(int, data[index:index + m]))
        B.append(row)
        index += m

    result = can_transform(A, B, n, m)
    if result == [-1]:
        print(-1)
    else:
        print(len(result))
        print(' '.join(map(str, result)))

if __name__ == "__main__":
    main()
